import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import { splitProps } from 'solid-js';
import styles from './Separator.module.css';

type SeparatorOrientation = 'horizontal' | 'vertical';
type SeparatorSize = 'xs' | 'sm' | 'md' | 'lg';
type SeparatorVariant = 'solid' | 'dashed' | 'dotted';

type SeparatorRootProps = HTMLArkProps<'span'> & {
  orientation?: SeparatorOrientation;
  size?: SeparatorSize;
  variant?: SeparatorVariant;
};

function Separator(props: SeparatorRootProps) {
  const [local, others] = splitProps(props, [
    'aria-orientation',
    'class',
    'orientation',
    'role',
    'size',
    'variant',
  ]);
  const orientation = () => local.orientation ?? 'horizontal';
  const role = () => local.role ?? 'separator';

  return (
    <ark.span
      {...others}
      role={role()}
      aria-orientation={role() === 'separator' ? orientation() : undefined}
      data-scope="separator"
      data-part="root"
      data-slot="separator-root"
      data-orientation={orientation()}
      data-size={local.size ?? 'sm'}
      data-variant={local.variant ?? 'solid'}
      class={clsx(styles.root, local.class)}
    />
  );
}

export { Separator };
export type { SeparatorOrientation, SeparatorRootProps, SeparatorSize, SeparatorVariant };

@layer moduix.components {
  .root {
    --_separator-thickness: var(--moduix-border-width-sm);

    display: block;
    flex-shrink: 0;
    margin: 0;
    border: 0 solid var(--moduix-separator-color, var(--moduix-color-border));

    &[data-size='xs'] {
      --_separator-thickness: 0.5px;
    }

    &[data-size='md'] {
      --_separator-thickness: var(--moduix-border-width-md);
    }

    &[data-size='lg'] {
      --_separator-thickness: 3px;
    }

    &[data-variant='dashed'] {
      border-style: dashed;
    }

    &[data-variant='dotted'] {
      border-style: dotted;
    }

    &[data-orientation='horizontal'] {
      width: 100%;
      height: 0;
      border-block-start-width: var(--moduix-separator-thickness, var(--_separator-thickness));
    }

    &[data-orientation='vertical'] {
      width: 0;
      height: 1em;
      border-inline-start-width: var(--moduix-separator-thickness, var(--_separator-thickness));
    }
  }
}
